(function () {
  function _enum_from_string(v, allowed) {
    if (!Array.isArray(allowed) || allowed.length === 0) {
      throw new Error("_enum requires allowed values");
    }
    for (const item of allowed) {
      if (item === v || String(item) === String(v)) {
        return v;
      }
    }
    throw new Error(
      "expected one of [" + allowed.map(String).join(", ") + "]",
    );
  }

  function _enum_to_string(v) {
    return String(v);
  }

  return { _enum_from_string, _enum_to_string };
})
